  // - show the loading state before the request resolves
  // - map an empty list to 'empty' and a non-empty list to 'success'
  // - map a rejection to 'error' with a readable message
  // - ignore a response that arrives after `mode` has changed again (stale response)

  // TODO: make Retry run the request again with the current mode.
  function handleRetry() {}

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Team Directory</h1>
          <p className="subtitle">Load the team from a fake API and render every request state.</p>
        </header>

        <div className="field">
          <label className="label" htmlFor="mode-select">Data source</label>
          <select
            id="mode-select"
            className="mode"
            value={mode}
            onChange={(event: React.ChangeEvent<HTMLSelectElement>) => setMode(event.target.value as SourceMode)}
          >
            <option value="ok">Team (6 members)</option>
            <option value="empty">Empty team</option>
            <option value="flaky">Flaky network</option>
          </select>
        </div>

        <div className="status-row">
          {/* TODO: render exactly one status line:
              <span className="status status--loading">Loading team…</span>
              <span className="status status--error" role="alert">Could not load the team: {message}</span>
              <span className="status status--muted">{count} members</span> */}
        </div>

        {/* TODO: on error, render
            <button type="button" className="retry" onClick={handleRetry}>Retry</button> */}

        {/* TODO: on success, render <ul className="results"> with one
            <li className="user-row"> per member, holding
            <div className="user-name"> and <div className="user-role">. */}

        {/* TODO: on empty, render <p className="empty">No team members yet.</p> */}
